-- schema.sql
-- รันไฟล์นี้ "ก่อน" import ข้อมูลจาก schemas.sql เดิม (schemas.sql มีแต่ INSERT ไม่มี CREATE TABLE)
--
-- วิธีรัน (ตัวอย่าง):
--   mysql -u root -p fund_dashboard < schema.sql
--   mysql -u root -p fund_dashboard < schemas.sql   (ไฟล์ข้อมูลเดิมที่มีอยู่แล้ว)

CREATE DATABASE IF NOT EXISTS fund_dashboard
    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE fund_dashboard;

CREATE TABLE IF NOT EXISTS members (
    id            INT AUTO_INCREMENT PRIMARY KEY,
    branch        VARCHAR(100) NOT NULL DEFAULT 'comsci41',
    name          VARCHAR(255) NOT NULL,
    amount        DECIMAL(10,2) NOT NULL DEFAULT 100.00,
    paid_months   JSON NOT NULL,   -- เช่น [false,false,...,false] ยาว 12 ช่อง
    paid_weeks    JSON NOT NULL,   -- เช่น [false,false,...,false] ยาว 52 ช่อง
    history       JSON NOT NULL,   -- เช่น [{date, method, amount, months|weeks}, ...]
    updated_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
                     ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS settings (
    `key`         VARCHAR(64) PRIMARY KEY,
    `value`       VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ค่าเริ่มต้นของเป้าหมายเก็บเงิน (แทนที่ localStorage เดิม จะได้ sync ข้ามเครื่อง/อุปกรณ์ได้)
INSERT INTO settings (`key`, `value`) VALUES ('target_amount', '4000')
    ON DUPLICATE KEY UPDATE `value` = VALUES(`value`);

-- หมายเหตุ: ไฟล์ schemas.sql เดิมของคุณมีคอลัมน์ paid_months เป็น string
-- แบบ '[false, false, ...]' ซึ่งจริงๆ แล้วเป็น JSON ที่ถูกต้องอยู่แล้ว (JSON ใช้ false ตัวเล็ก)
-- ดังนั้น INSERT เดิมยังใช้ import เข้าคอลัมน์ชนิด JSON นี้ได้ตรงๆ
-- แต่จะไม่มีคอลัมน์ paid_weeks / history อยู่ในไฟล์เดิม ให้รันคำสั่งเติมค่า default ให้แถวเก่าดังนี้:
--
-- UPDATE members SET paid_weeks = JSON_ARRAY(
--   false,false,false,false,false,false,false,false,false,false,
--   false,false,false,false,false,false,false,false,false,false,
--   false,false,false,false,false,false,false,false,false,false,
--   false,false,false,false,false,false,false,false,false,false,
--   false,false,false,false,false,false,false,false,false,false,
--   false,false
-- ) WHERE paid_weeks IS NULL;
--
-- UPDATE members SET history = JSON_ARRAY() WHERE history IS NULL;